var t=[{title:`Veelvoorkomende soorten carries`,text:`Bij een farmer’s carry draag je in elke hand één gewicht. Bij een suitcase carry draag je één gewicht aan één kant, zodat je romp zijwaarts buigen moet weerstaan. Bij een front carry houd je de last dicht bij je borst, en een carry boven het hoofd vraagt meer schouderstabiliteit en meer ruimte boven je. Elke positie verandert de betrokken spieren en de vaardigheid.`},{title:`Basistechniek`,text:`Kies een gewicht dat je de hele wandeling stevig vast kunt houden, sta rechtop in een comfortabele houding en loop met bewuste stappen. Houd het gewicht stevig vast, leun niet ver naar het gewicht toe of ervan af en blijf ademen tijdens een lange wandeling. Loop langzamer in bochten en houd je pad vrij.`},{title:`Carries doseren`,text:`Carries tel je op afstand of tijd in plaats van herhalingen. Draag bijvoorbeeld twee dumbbells die je 20–30 seconden stabiel kunt vasthouden, rust en herhaal dan. Blijven je grip en houding gelijk, voeg dan wat afstand, tijd of gewicht toe. Een zwaarder gewicht helpt niet als je daardoor haastige, ongelijke stappen maakt.`},{title:`Ruimte en veiligheid`,text:`Controleer of je route genoeg vrije vloer heeft, een antislipondergrond en geen mensen of voorwerpen in de weg. Zet de gewichten beheerst neer en laat ze niet vallen. Sla carries boven het hoofd over onder een laag plafond of als je niet zeker bent van je schoudercontrole. Train eenzijdige carries altijd aan beide kanten.`},{title:`TrainUp gebruiken`,text:`Carries kunnen een krachtplek in je schema invullen als je de uitrusting en de ruimte hebt om te lopen. Je schema controleert de vloeroppervlakte die je in Profiel hebt ingesteld. Beperken je rug of handen hoeveel belasting op de wervelkolom of gripwerk je aankunt, voeg dat lichaamsdeel dan toe als beperking in Profiel, zodat het schema oefeningen kan weglaten die niet passen.`}];var a=[{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};